dashboard.definition:
{
    "title": "Host detail",
    "description": "Everything about one host: what it should send and how late each item is, its data over 24 hours, its Splunk agent, recent agent errors, tamper findings, status changes and Hyper-V events.",
    "inputs": {
        "input_host": {
            "type": "input.dropdown",
            "title": "Host",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "host",
                "selectFirstSearchResult": true
            },
            "dataSources": {
                "primary": "ds_hosts"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-24h",
                        "latest": "now"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_hosts": {
            "type": "ds.search",
            "name": "Hosts",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | stats max(eval(if(level==\"host\", host_rollup, null()))) as rollup by host | eval label=host.if(isnotnull(rollup), \" (\".rollup.\")\", \"\"), value=host | table label value"
            }
        },
        "ds_children": {
            "type": "ds.search",
            "name": "Children",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | where host==$host|s$ | `dh_ui_host_children(dh_volume)` | `dh_ui_headers`"
            }
        },
        "ds_chart": {
            "type": "ds.search",
            "name": "24 h by sourcetype (tstats)",
            "options": {
                "query": "| tstats prestats=t count where index IN (`dh_indexes`) [| makeresults | eval host=$host|s$ | `dh_ui_host_terms`] earliest=-24h latest=now by _time span=10m sourcetype | timechart span=10m count by sourcetype",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_fwd": {
            "type": "ds.search",
            "name": "Forwarder",
            "options": {
                "query": "| inputlookup dh_fwd where host=$host|s$ | `dh_ui_fwd(now())` | `dh_ui_headers`"
            }
        },
        "ds_errors": {
            "type": "ds.search",
            "name": "Latest splunkd errors",
            "options": {
                "query": "search index=_internal sourcetype=splunkd (log_level=ERROR OR log_level=WARN) [| makeresults | eval host=$host|s$ | `dh_ui_host_terms`] earliest=-24h latest=now | head 25 | eval time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), message=coalesce(event_message, _raw) | eval level=log_level | table time level component message | `dh_ui_headers`"
            }
        },
        "ds_tamper": {
            "type": "ds.search",
            "name": "Tamper findings",
            "options": {
                "query": "| inputlookup dh_tamper where host=$host|s$ | where coalesce(tonumber(suppressed), 0)==0 | sort 0 -time | eval time=strftime(tonumber(time), \"%Y-%m-%d %H:%M\") | table time indicator events code detail finding_id | `dh_ui_headers`"
            }
        },
        "ds_transitions": {
            "type": "ds.search",
            "name": "Transitions (7 d)",
            "options": {
                "query": "search index=data_health source=\"dh:transition\" sourcetype=stash dh_host=$host|s$ earliest=-7d latest=+1d | sort 0 -_time | head 200 | eval time=strftime(_time, \"%Y-%m-%d %H:%M\") | table time entity_id prev_status status cause | `dh_ui_headers`"
            }
        },
        "ds_hyperv": {
            "type": "ds.search",
            "name": "Hyper-V events (7 d)",
            "options": {
                "query": "search index=windows sourcetype=XmlWinEventLog source=\"XmlWinEventLog:Microsoft-Windows-Hyper-V-Worker-Admin\" $host|s$ earliest=-7d latest=now | `dh_ui_hyperv` | where host==$host|s$ | head 50 | `dh_ui_headers`"
            }
        },
        "ds_runbooks": {
            "type": "ds.search",
            "name": "Runbooks",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | where host==$host|s$ AND isnotnull(runbook) AND match(runbook, \"^https?://\") | stats count as entities by runbook | `dh_ui_headers`"
            }
        }
    },
    "visualizations": {
        "viz_children": {
            "type": "splunk.table",
            "title": "Expected data from this host",
            "description": "Each stream this host should send: its status and how late it is against its limit. Guide (project repo): docs/data-health/dashboards.md > Host detail > Expected data from this host",
            "dataSources": {
                "primary": "ds_children"
            },
            "options": {
                "count": 25
            }
        },
        "viz_chart": {
            "type": "splunk.column",
            "title": "Events in the last 24 h by sourcetype",
            "dataSources": {
                "primary": "ds_chart"
            },
            "options": {
                "stackMode": "stacked"
            },
            "description": "How much data arrived from this host over the day. Guide (project repo): docs/data-health/dashboards.md > Host detail > Events in the last 24 h by sourcetype"
        },
        "viz_fwd": {
            "type": "splunk.table",
            "title": "Forwarder (the Splunk agent on the host)",
            "dataSources": {
                "primary": "ds_fwd"
            },
            "options": {
                "count": 25
            },
            "description": "Version and last contact of the Splunk agent and the last Ansible and VM events. Guide (project repo): docs/data-health/dashboards.md > Host detail > Forwarder (the Splunk agent on the host)"
        },
        "viz_errors": {
            "type": "splunk.table",
            "title": "Latest Splunk agent errors and warnings (24 h)",
            "dataSources": {
                "primary": "ds_errors"
            },
            "options": {
                "count": 25
            },
            "description": "What the Splunk agent on this host complained about. Guide (project repo): docs/data-health/dashboards.md > Host detail > Latest Splunk agent errors and warnings (24 h)"
        },
        "viz_tamper": {
            "type": "splunk.table",
            "title": "Tamper findings on this host",
            "dataSources": {
                "primary": "ds_tamper"
            },
            "options": {
                "count": 25
            },
            "description": "Signs that someone may have switched off logging here. Guide (project repo): docs/data-health/dashboards.md > Host detail > Tamper findings on this host"
        },
        "viz_transitions": {
            "type": "splunk.table",
            "title": "Status changes (7 d)",
            "dataSources": {
                "primary": "ds_transitions"
            },
            "options": {
                "count": 25
            },
            "description": "When each stream went late or missing and when it came back. Guide (project repo): docs/data-health/dashboards.md > Host detail > Status changes (7 d)"
        },
        "viz_hyperv": {
            "type": "splunk.table",
            "title": "Hyper-V VM events (7 d)",
            "dataSources": {
                "primary": "ds_hyperv"
            },
            "options": {
                "count": 25
            },
            "description": "When this VM was started or stopped on the Hyper-V host. Guide (project repo): docs/data-health/dashboards.md > Host detail > Hyper-V VM events (7 d)"
        },
        "viz_runbooks": {
            "type": "splunk.table",
            "title": "Runbooks (click to open)",
            "dataSources": {
                "primary": "ds_runbooks"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "$row.Runbook.value$",
                        "newTab": true
                    }
                }
            ],
            "description": "The how-to pages linked to this host. Guide (project repo): docs/data-health/dashboards.md > Host detail > Runbooks (click to open)"
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1440,
            "height": 1700
        },
        "globalInputs": [
            "input_host"
        ],
        "structure": [
            {
                "item": "viz_children",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 1440,
                    "h": 400
                }
            },
            {
                "item": "viz_chart",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 400,
                    "w": 960,
                    "h": 320
                }
            },
            {
                "item": "viz_fwd",
                "type": "block",
                "position": {
                    "x": 960,
                    "y": 400,
                    "w": 480,
                    "h": 320
                }
            },
            {
                "item": "viz_errors",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 720,
                    "w": 1440,
                    "h": 320
                }
            },
            {
                "item": "viz_tamper",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1040,
                    "w": 720,
                    "h": 320
                }
            },
            {
                "item": "viz_transitions",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1040,
                    "w": 720,
                    "h": 320
                }
            },
            {
                "item": "viz_hyperv",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 1360,
                    "w": 720,
                    "h": 340
                }
            },
            {
                "item": "viz_runbooks",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 1360,
                    "w": 720,
                    "h": 340
                }
            }
        ]
    }
}
